// "What exactly changes" for the approval dialog. SECURITY: this builds lines from the typed params only, and the
// params never carry values (contracts/env.ts). Values are shown as a masked source ("generated by the server",
// "typed by you", "copied from ..."), never as text. Even if a caller smuggled a `value` field in, it is not read.
import type { ActionParams, DbField, EnvChange } from "@/lib/contracts";

export type DiffSign = "+" | "-" | "~";

export type MaskedSource =
  | { kind: "generated" }
  | { kind: "user" }
  | { kind: "existing"; from: string }
  | { kind: "db"; db: string; field: DbField };

export type DiffLabelKey =
  | "restart"
  | "scaleOn"
  | "scaleOff"
  | "port"
  | "plan"
  | "redeploy"
  | "stepCreateApp"
  | "stepCreateDb"
  | "stepDeploy"
  | "stepDeployUpload"
  | "stepDeployImage"
  | "stepGuidance"
  | "stepGuidanceNoDomain"
  | "wire";

export interface DiffLine {
  sign: DiffSign;
  /** Plan step id (deploy_plan only). */
  step?: string;
  /** LTR token: env key. */
  code?: string;
  /** Masked value source for `+ KEY = ••••••(...)` lines. */
  value?: MaskedSource;
  /** Sentence template key + params (identifiers inside params render as LTR). */
  label?: { key: DiffLabelKey; params: Record<string, string | number> };
}

export const MASK = "••••••";

function envLine(c: EnvChange, step?: string): DiffLine {
  const base = step ? { step } : {};
  if (c.op === "unset") return { ...base, sign: "-", code: c.key };
  switch (c.valueSource) {
    case "generated":
      return { ...base, sign: "+", code: c.key, value: { kind: "generated" } };
    case "user":
      return { ...base, sign: "+", code: c.key, value: { kind: "user" } };
    case "existing":
      return {
        ...base,
        sign: "+",
        code: c.key,
        value: c.from.kind === "db" ? { kind: "db", db: c.from.name, field: c.from.field } : { kind: "existing", from: c.from.key },
      };
  }
}

const label = (key: DiffLabelKey, params: Record<string, string | number>, sign: DiffSign = "~", step?: string): DiffLine => ({
  sign,
  ...(step ? { step } : {}),
  label: { key, params },
});

export function buildDiff(params: ActionParams): DiffLine[] {
  switch (params.type) {
    case "restart":
      return [label("restart", { name: params.app })];
    case "set_env":
      return params.changes.map((c) => envLine(c));
    case "unset_env":
      return params.keys.map((key): DiffLine => ({ sign: "-", code: key }));
    case "scale":
      return [label(params.scale === 1 ? "scaleOn" : "scaleOff", { name: params.resource.name })];
    case "update_port":
      return [label("port", { name: params.app, port: params.port })];
    case "resize":
      return [label("plan", { name: params.resource.name, plan: params.planId })];
    case "redeploy_previous":
      return [label("redeploy", { name: params.app, release: params.releaseId })];
    case "wire_db":
      return wireLines(params.db, params.app, params.mapping);
    case "deploy_plan":
      return params.plan.steps.flatMap((s): DiffLine[] => {
        switch (s.kind) {
          case "create_app":
            return [label("stepCreateApp", { name: s.name, platform: s.platform, plan: s.planId }, "+", s.id)];
          case "create_db":
            return [label("stepCreateDb", { name: s.name, engine: s.engine, version: s.version, plan: s.planId }, "+", s.id)];
          case "set_env":
            return s.changes.map((c) => envLine(c, s.id));
          case "wire_db":
            return wireLines(s.db, s.app, s.mapping, s.id);
          case "deploy":
            return [
              label("stepDeploy", { app: s.app, port: s.port }, "~", s.id),
              label(s.source.kind === "upload" ? "stepDeployUpload" : "stepDeployImage", s.source.kind === "image" ? { image: s.source.image } : {}, "~", s.id),
            ];
          case "domain_guidance":
            return [
              s.domain ? label("stepGuidance", { domain: s.domain }, "~", s.id) : label("stepGuidanceNoDomain", {}, "~", s.id),
            ];
        }
      });
    default:
      return [];
  }
}

function wireLines(db: string, app: string, mapping: Partial<Record<DbField, string>>, step?: string): DiffLine[] {
  const head = label("wire", { app, db }, "~", step);
  const rows = (Object.entries(mapping) as Array<[DbField, string | undefined]>)
    .filter((e): e is [DbField, string] => typeof e[1] === "string")
    .map(([field, key]): DiffLine => ({ sign: "+", ...(step ? { step } : {}), code: key, value: { kind: "db", db, field } }));
  return [head, ...rows];
}
